def count_even_substrings(s):
    n = len(s)
    count = 0
    for l in range(n):
        for r in range(l, n):
            if int(s[l:r+1]) % 2 == 0:
                count += 1
    return count

# Read input
n = int(input().strip())
s = input().strip()

# Calculate and print the result
print(count_even_substrings(s))
